/**
 * GitHub App installation-token permission requirements per REST endpoint.
 *
 * Snapshot of `src/github-apps/data/fpt-2022-11-28/server-to-server-permissions.json`
 * from github/docs taken on 2026-09-03, flattened to `<VERB> <path> <permission>:<access>`
 * lines. Refresh it with:
 *
 *   gh api -H "Accept: application/vnd.github.raw" \
 *     repos/github/docs/contents/src/github-apps/data/fpt-2022-11-28/server-to-server-permissions.json \
 *     | jq -r 'to_entries[] | .key as $p | .value.permissions[] | select(.["server-to-server"])
 *       | "\(.verb|ascii_upcase) \(.requestPath) \($p):\(.access)"' | sort -u
 */
export interface GithubAppEndpointPermission {
  permission: string;
  access: 'read' | 'write' | 'admin';
}

/** Keyed by `<VERB> <path>` with every `{param}` placeholder normalized to `{}`. */
export function githubAppEndpointPermissions(): Map<string, GithubAppEndpointPermission[]> {
  const byRoute = new Map<string, GithubAppEndpointPermission[]>();
  for (const line of GITHUB_APP_ENDPOINT_PERMISSIONS.trim().split('\n')) {
    const separator = line.lastIndexOf(' ');
    const route = normalizeGithubRoute(line.slice(0, separator));
    const [permission, access] = line.slice(separator + 1).split(':');
    if (!permission || (access !== 'read' && access !== 'write' && access !== 'admin')) {
      throw new Error(`Malformed GitHub endpoint permission line: ${line}`);
    }
    const entries = byRoute.get(route) ?? [];
    entries.push({permission, access});
    byRoute.set(route, entries);
  }
  return byRoute;
}

export function normalizeGithubRoute(route: string): string {
  return route.replaceAll(/\{[^}]+\}/gu, '{}');
}

